import{_ as n}from"./chunks/Audio.COine8Wh.js";import{_ as t}from"./chunks/Tags.BJ536pW3.js";import{c as l,o as s,j as i,G as a,ae as o,a as r}from"./chunks/framework.Bw0Gm4PQ.js";const d=JSON.parse('{"title":"Investing in All of America Act of 2025","description":"","frontmatter":{"legisId":"2026-05-19-investing-in-all-of-america-act-of-2025","title":"Investing in All of America Act of 2025","displayTitle":"Investing in All of America Act of 2025","lawNumber":"119-92","billNumber":"H.R. 2066","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ92.xml","publishDate":"2026-05-19T00:00:00-05:00","industries":["finance","manufacturing","technology"],"agencies":[],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Investing in All of America Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-19-investing-in-all-of-america-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Investing in All of America Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-19-investing-in-all-of-america-act-of-2025\\",\\"datePublished\\":\\"2026-05-19T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-19-investing-in-all-of-america-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-05-19-investing-in-all-of-america-act-of-2025.md","filePath":"congress-bills/2026-05-19-investing-in-all-of-america-act-of-2025.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2026-05-19-investing-in-all-of-america-act-of-2025.md"},v=Object.assign(c,{setup(m){return(f,e)=>(s(),l("div",null,[e[0]||(e[0]=i("h1",{id:"investing-in-all-of-america-act-of-2025",tabindex:"-1"},[r("Investing in All of America Act of 2025 "),i("a",{class:"header-anchor",href:"#investing-in-all-of-america-act-of-2025","aria-label":'Permalink to "Investing in All of America Act of 2025"'},"​")],-1)),a(n),a(t,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Tuesday, May 19, 2026. Public Law 119-92, H.R. 2066.</p><p><strong>Headline:</strong> The law expands federal leverage capacity for small-business investment funds while favoring investments in underserved areas, critical technologies, and manufacturing.</p><p><strong>Why it matters:</strong> Small Business Investment Companies can access more federally backed capital and exclude certain priority investments from leverage calculations, potentially directing more financing toward targeted small businesses.</p><p><strong>What the law does:</strong></p><ul><li>Raises leverage caps to $250 million for a single company making quarterly or semiannual interest payments and $175 million for other companies.</li><li>Raises combined leverage caps for commonly controlled companies to $475 million with quarterly or semiannual payments and $350 million otherwise.</li><li>Excludes qualifying investments in low-income or rural areas, critical technology fields, and small manufacturers from leverage calculations.</li><li>Caps exclusions at the lesser of 50 percent of private capital or $125 million while retaining the overall 200-percent leverage limit.</li><li>Limits the exclusion to qualifying investments made after enactment.</li><li>Generally excludes government funds from private capital, with exceptions for specified pension, educational, foundation, endowment, and trust funds.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Small Business Investment Companies seeking federal leverage.</li><li>Small businesses in low-income or rural communities.</li><li>Small manufacturers and businesses operating in covered critical technology fields.</li><li>Public pension, college, university, foundation, endowment, and trust funds that may qualify as private capital.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Entrepreneurs in targeted communities and industries may have greater access to investment capital.</li><li>Workers and residents may see more small-business financing directed toward rural, low-income, manufacturing, and critical technology markets.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="investing-in-all-of-america-act-of-2025-1" tabindex="-1">Investing in All of America Act of 2025 <a class="header-anchor" href="#investing-in-all-of-america-act-of-2025-1" aria-label="Permalink to &quot;Investing in All of America Act of 2025&quot;">​</a></h3><p>The law changes federal leverage limits for Small Business Investment Companies and allows certain qualifying investments to be left out when calculating those limits. The exclusion covers investments in small businesses in low-income or rural areas, critical technology fields, and small manufacturing, subject to a cap and only for investments made after enactment.</p><p><strong>Key takeaways:</strong></p><ul><li>A single investment company may generally use leverage up to 200 percent of its private capital, subject to a dollar cap of $250 million for companies making quarterly or semiannual interest payments and $175 million for other companies.</li><li>Commonly controlled investment companies may have combined leverage of up to $475 million if they make quarterly or semiannual interest payments, or $350 million otherwise.</li><li>Qualifying investments in small businesses located in low-income or rural areas, operating primarily in covered critical technology categories, or meeting the definition of a small manufacturer may be excluded from leverage calculations.</li><li>The total exclusion cannot exceed the lesser of 50 percent of the company or companies’ private capital or $125 million, and the general 200-percent leverage limit still applies.</li><li>Only qualifying investments made after the law’s enactment are eligible for the exclusion.</li><li>Government funds generally do not count as private capital when federal leverage is approved, except for specified qualifying funds such as certain public pension, college, university, foundation, endowment, or trust funds.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ92.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ92.xml</a></p>',15))]))}});export{d as __pageData,v as default};
